"""Browser-only realtime dashboard; no external assets required."""
from __future__ import annotations
from flask import Flask, jsonify, request

PAGE = r'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pi FPGA IDS</title><style>
:root{--bg:#07111f;--card:#101f35;--edge:#263e60;--text:#eaf3ff;--sub:#9ab0ce;--blue:#45caff;--ok:#37d996;--warn:#ffc45b;--bad:#ff6e81}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top right,#1b416e 0,#07111f 44%);color:var(--text);font:14px Inter,system-ui,sans-serif}.page{max-width:1300px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.title{display:flex;gap:12px;align-items:center}.icon{width:44px;height:44px;border:1px solid var(--blue);border-radius:13px;display:grid;place-items:center;color:var(--blue);font-weight:800}.title h1{margin:0;font-size:20px}.title p{margin:3px 0;color:var(--sub);font-size:12px}.updated{font-size:12px;color:var(--sub)}.layout{display:grid;gap:14px}.three{grid-template-columns:repeat(3,1fr)}.four{grid-template-columns:repeat(4,1fr)}.two{grid-template-columns:1.35fr 1fr}.card{background:linear-gradient(140deg,#14263f,#0c182b);border:1px solid var(--edge);border-radius:15px;padding:17px;box-shadow:0 15px 40px #0003}.label{font-size:11px;color:var(--sub);letter-spacing:.1em;text-transform:uppercase}.value{font-size:28px;font-weight:750;margin:9px 0 2px}.sub{font:12px ui-monospace,monospace;color:var(--sub);margin-top:7px}.state{display:flex;align-items:center;gap:9px;font-weight:650;font-size:16px;margin:11px 0 4px}.badge{font-size:10px;padding:5px 8px;border-radius:99px;font-weight:800;letter-spacing:.08em;background:#193c32;color:var(--ok)}.warn{background:#4d3b1c;color:var(--warn)}.bad{background:#51222d;color:var(--bad)}.bar{height:8px;background:#081322;border-radius:99px;overflow:hidden;margin:12px 0 4px}.bar i{height:100%;display:block;background:linear-gradient(90deg,var(--blue),var(--ok));transition:width .35s}.model{border-color:#3479a7}.upload{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:14px}input[type=file]{max-width:330px;color:var(--sub)}button{border:0;border-radius:8px;padding:10px 14px;background:var(--blue);color:#032038;font-weight:750;cursor:pointer}button:disabled{opacity:.55}.message{font-size:12px;color:var(--sub)}.keys{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:13px}.key{padding:10px;border:1px solid #203755;background:#091524;border-radius:9px}.key span{display:block;color:var(--sub);font-size:10px;text-transform:uppercase}.key b{display:block;margin-top:4px;font:18px ui-monospace,monospace}.row{display:flex;justify-content:space-between;border-bottom:1px solid #20324d;padding:10px 0}.row span{color:var(--sub)}.events{max-height:280px;overflow:auto;margin-top:10px}.event{border-bottom:1px solid #20324d;padding:10px 0;font:12px ui-monospace,monospace}.event time{color:var(--sub);margin-right:7px}.event.error{color:#ffb2bd}@media(max-width:850px){.three,.four,.two{grid-template-columns:1fr 1fr}}@media(max-width:540px){.page{padding:16px}.three,.four,.two,.keys{grid-template-columns:1fr}.updated{display:none}}
</style></head><body><main class="page"><header><div class="title"><div class="icon">IDS</div><div><h1>Pi · FPGA IDS Console</h1><p>Giám sát Ethernet, UART và model FPGA theo thời gian thực</p></div></div><div id="updated" class="updated">Đang kết nối…</div></header>
<section class="layout three"><div class="card"><div class="label">Ethernet capture</div><div class="state"><b id="capB" class="badge">—</b><span id="capS">Đang khởi tạo</span></div><div id="capD" class="sub">—</div></div><div class="card"><div class="label">Liên kết UART FPGA</div><div class="state"><b id="uartB" class="badge">—</b><span id="uartS">Đang khởi tạo</span></div><div id="uartD" class="sub">—</div></div><div class="card"><div class="label">Pipeline</div><div class="state"><b id="pipeB" class="badge">—</b><span id="pipeS">Chờ model</span></div><div id="pipeD" class="sub">Không hiển thị accuracy khi traffic không có nhãn.</div></div></section>
<section class="card model" style="margin-top:14px"><div class="label">FPGA model image · 1,273 nodes</div><div class="state"><b id="modelB" class="badge warn">INACTIVE</b><span id="modelS">Chưa có model active</span></div><div class="bar"><i id="modelBar"></i></div><div class="sub">Tiến trình: <span id="modelCount">0/1273</span> · CRC32: <span id="modelCrc">—</span> · Model version: <span id="modelVersion">—</span></div><form id="uploadForm" class="upload"><input id="modelFile" name="file" type="file" accept=".hex" required><button id="uploadButton" type="submit">Lưu và nạp vào FPGA</button><span id="uploadMessage" class="message">Chọn file node_rom.hex để bắt đầu.</span></form></section>
<section class="layout four" style="margin-top:14px"><div class="card"><div class="label">Captured records</div><div id="captures" class="value">0</div><div id="capRate" class="sub">0.00 records/s</div></div><div class="card"><div class="label">UART results</div><div id="results" class="value">0</div><div id="resRate" class="sub">0.00 results/s</div></div><div class="card"><div class="label">Capture throughput</div><div id="speed" class="value">0 B/s</div><div id="total" class="sub">0 total bytes</div></div><div class="card"><div class="label">Transport faults</div><div id="faults" class="value">0</div><div id="faultD" class="sub">retry 0 · timeout 0 · CRC 0</div></div></section>
<section class="layout two" style="margin-top:14px"><div class="card"><div class="label">Kết quả inference gần nhất</div><div class="keys"><div class="key"><span>Sequence</span><b id="seq">—</b></div><div class="key"><span>Class ID</span><b id="class">—</b></div><div class="key"><span>Model version</span><b id="resultModel">—</b></div><div class="key"><span>Leaf node</span><b id="leaf">—</b></div><div class="key"><span>Steps</span><b id="steps">—</b></div><div class="key"><span>Error code</span><b id="resultError">—</b></div></div><div class="row"><span>Capture gần nhất</span><b id="lastCap">—</b></div><div class="row"><span>Result gần nhất</span><b id="lastRes">—</b></div><div class="row"><span>IP nguồn gần nhất</span><b id="source">—</b></div></div><div class="card"><div class="label">Operational events</div><div id="events" class="events">Chưa có sự kiện.</div></div></section></main>
<script>const $=x=>document.getElementById(x),put=(x,v)=>$(x).textContent=v,num=x=>new Intl.NumberFormat().format(x||0),rate=x=>(x||0).toFixed(2),tm=x=>x?new Date(x).toLocaleString():'—',size=x=>{x=x||0;for(const u of ['B','KB','MB']){if(x<1024||u==='MB')return (x<10&&u!='B'?x.toFixed(1):Math.round(x))+' '+u;x/=1024}};function badge(id,state){let b=$(id);b.textContent=(state||'unknown').toUpperCase();b.className='badge '+(state==='active'||state==='connected'?'':state==='error'||state==='disconnected'?'bad':'warn')}function link(id,x){badge(id+'B',x.state);put(id+'S',x.label||x.state||'—');put(id+'D',x.detail||'—')}function draw(s){link('cap',s.connections.capture);link('uart',s.connections.uart);let m=s.model||{};badge('modelB',m.state);put('modelS',m.detail||'—');put('modelCount',`${m.accepted_count||0}/${m.node_count||1273}`);put('modelCrc',m.crc32||'—');put('modelVersion',m.active_version??'—');$('modelBar').style.width=Math.min(100,100*(m.accepted_count||0)/(m.node_count||1273))+'%';let ready=m.state==='active';badge('pipeB',ready?'connected':m.state==='error'?'error':'inactive');put('pipeS',ready?'Sẵn sàng inference':m.state==='error'?'Model upload lỗi':'Chờ model active');put('pipeD',ready?'FEATURE được gửi sang FPGA.':'FEATURE sẽ được giữ lại cho đến khi COMMIT_ACK thành công.');put('captures',num(s.capture_count));put('results',num(s.result_count));put('capRate',rate(s.capture_rate_pps)+' records/s');put('resRate',rate(s.result_rate_pps)+' results/s');put('speed',size(s.capture_bytes_per_second)+'/s');put('total',size(s.capture_bytes)+' total bytes');put('faults',num(s.retries+s.timeouts+s.crc_errors));put('faultD',`retry ${s.retries} · timeout ${s.timeouts} · CRC ${s.crc_errors}`);[['seq',s.last_sequence],['class',s.class_id],['resultModel',s.model_version],['leaf',s.leaf_node],['steps',s.step_count],['resultError',s.error_code]].forEach(x=>put(x[0],x[1]??'—'));put('lastCap',tm(s.last_capture_at));put('lastRes',tm(s.last_result_at));put('source',s.last_source||'—');$('events').innerHTML=(s.events||[]).slice().reverse().map(e=>`<div class="event ${e.level||''}"><time>${tm(e.time)}</time>${e.message}</div>`).join('')||'Chưa có sự kiện.';put('updated','Cập nhật '+new Date().toLocaleTimeString())}async function poll(){try{let r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error();draw(await r.json())}catch(e){put('updated','Mất kết nối dashboard')}}$('uploadForm').onsubmit=async e=>{e.preventDefault();let f=$('modelFile').files[0];if(!f)return;let b=$('uploadButton');b.disabled=true;put('uploadMessage','Đang kiểm tra và lưu file…');try{let d=new FormData();d.append('file',f);let r=await fetch('/api/model/upload',{method:'POST',body:d});let j=await r.json();put('uploadMessage',j.message||j.error||'Không thể bắt đầu upload.')}catch(e){put('uploadMessage','Lỗi kết nối tới server.')}finally{b.disabled=false}};poll();setInterval(poll,1000)</script></body></html>'''

def make_app(state, model_service=None):
    app = Flask(__name__)
    @app.get("/api/status")
    def status(): return jsonify(state.snapshot())
    @app.post("/api/model/upload")
    def upload_model():
        if model_service is None: return jsonify(error="model service unavailable"), 503
        upload = request.files.get("file")
        if upload is None or not upload.filename.lower().endswith(".hex"): return jsonify(error="select a .hex model file"), 400
        try: return jsonify(model_service.save_and_start(upload))
        except (ValueError, OSError) as error: return jsonify(error=str(error)), 400
    @app.get("/")
    def dashboard(): return PAGE
    return app
